"use strict";(globalThis.webpackChunkuniwahl_doku||=[]).push([[7497],{1549(e,n,i){i.r(n),i.d(n,{assets:()=>a,contentTitle:()=>u,default:()=>o,frontMatter:()=>l,metadata:()=>r,toc:()=>d});const r=JSON.parse('{"id":"releases/6.1","title":"Version 6.1","description":"\ud83d\ude80 Diese Version integriert mehrsprachige Stimmzettel, optimiert Ihre Wahlprozesse durch sichere Aufbewahrung aller Texte und einer verbesserten Anbindung des uniWAHL Online-Wahlsystems und bietet eine aktualisierte Version der Online-Wahlkabine, die die Zug\xe4nglichkeit zum Wahlprozess verbessert, um eine noch breitere W\xe4hlerschaft zu erreichen.","source":"@site/docs/releases/6.1.md","sourceDirName":"releases","slug":"/releases/6.1","permalink":"/uniwahl-doku/pr-preview/pr-6/releases/6.1","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Version 6.1"},"sidebar":"doku","previous":{"title":"Version 6.2","permalink":"/uniwahl-doku/pr-preview/pr-6/releases/6.2"},"next":{"title":"Version 6.0","permalink":"/uniwahl-doku/pr-preview/pr-6/releases/6.0"}}');var t=i(4848),s=i(8453);const l={title:"Version 6.1"},u=void 0,a={},d=[];function h(e){const n={li:"li",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.p,{children:"\ud83d\ude80 Diese Version integriert mehrsprachige Stimmzettel, optimiert Ihre Wahlprozesse durch sichere Aufbewahrung aller Texte und einer verbesserten Anbindung des uniWAHL Online-Wahlsystems und bietet eine aktualisierte Version der Online-Wahlkabine, die die Zug\xe4nglichkeit zum Wahlprozess verbessert, um eine noch breitere W\xe4hlerschaft zu erreichen."}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Vorschau der Online-Wahlkabine"}),": Die Vorschau der Stimmzettel des Online-Wahlsystems direkt in der uniWAHL Kernsoftware ist eine neue Funktion, die eine nahtlose Ansicht und Verwaltung der OWS-Daten direkt in uniWAHL erm\xf6glicht. Die Integration der Online-Wahlkabine f\xf6rdert so eine effizientere Verwaltung und \xdcberwachung aller Texte und Daten durch die Wahlleitung, was zu einer verbesserten Kontrolle und einem reibungsloseren Ablauf des Wahlprozesses insgesamt f\xfchren kann."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Mehrsprachige Stimmzettel (Papier, Online)"}),": Mit der erweiterten Textbausteinfunktion unterst\xfctzt uniWAHL 6.1 nun eine breitere Palette von Sprachen (DE,EN,FR,ES) und erm\xf6glicht die multilinguale Aufbereitung der Stimmzettel. Es k\xf6nnen sowohl die Bezeichnungen des Wahlprojekts, der Gremien und Wahlbereiche als auch die auf den Stimmzetteln enthaltenen Bestimmungstexte \xfcbersetzt werden. Alle Anleitungs- und Hinweistexte des uniWAHL Online-Wahlsystems k\xf6nnen ebenfalls angepasst und mehrsprachig \xfcbertragen werden. Diese Funktion f\xf6rdert die Zug\xe4nglichkeit und Benutzerfreundlichkeit der Wahl f\xfcr eine internationale W\xe4hlerschaft."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"OWS: Modernere Benutzeroberfl\xe4che der Online-Wahlkabine"}),": Die neue Version der Online-Wahlkabine pr\xe4sentiert sich in einer \xfcberarbeiteten Benutzeroberfl\xe4che, komplettiert mit einem neuen Inhaltsschema, das darauf abzielt, die Darstellung und Benutzerfreundlichkeit zu verbessern."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"OWS: Breadcrumb-Anzeige"}),": Die Einf\xfchrung einer Navigationsleiste erm\xf6glicht es den W\xe4hlenden, ihre aktuelle Position innerhalb des Wahlprozesses abzulesen und die n\xe4chsten Schritte zu erkennen. Durch diese Funktion bietet die Online-Wahlkabine noch bessere Orientierung und effizientere Navigation."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"OWS: Countdown"}),": Die Funktion zum zeitgesteuerten, automatischen Logout aus der Online-Wahlkabine ist eine Standardsicherheitsfunktion. Der Countdown-Timer oberhalb des Abmelde-Buttons bietet nun eine klare und direkte Anzeige der verbleibenden Restzeit bis zum Ende der Stimmabgabe, was f\xfcr eine bessere Zeitplanung sorgt."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"OWS: Multiple Authentifizierung (z.B. PIN/TAN- und SmartLink-Verfahren parallel)"}),": Die M\xf6glichkeit, mehrere Authentifizierungsmethoden parallel zu verwenden, bietet eine flexiblere Sicherheitsl\xf6sung f\xfcr die Anmeldung. Es k\xf6nnen mehrere Verfahren parallel eingesetzt werden, wie z.B. die gleichzeitige Integration des Zugangs zur Online-Wahlkabine in verschiedene Webplattformen oder den Versand der Zugangsdaten via E-Mail. Auch bei parallelen Anmeldeverfahren wird sichergesellt, das jeder wahlberechtigte Person nur einmal w\xe4hlen kann."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"OWS: Neues Stimmzettel-Layout (z.B. Ung\xfcltig unten darstellen, Listendarstellung verbessert)"}),": Das neue Layout f\xfcr Stimmzettel ist darauf ausgelegt, eine klarere und organisierte Darstellung der Wahlm\xf6glichkeiten zu bieten. So werden beispielsweise Listenwahlvorschl\xe4ge in Blockform dargestellt und besser ausgerichtet. Es kann gew\xe4hlt werden, ob die Option zum \u201eUng\xfcltig w\xe4hlen\u201c oben oder unten auf dem Stimmzettel dargestellt werden soll."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"OWS: Bessere Ladebildschirme"}),": Die optimierten Start- und Zwischensequenzen bieten w\xe4hrend des Ladeprozesses der Anwendung eine visuelle R\xfcckmeldung und \xfcberarbeitete Textbausteine. Die W\xe4hlenden bleiben so besser informiert und erleben eine bessere Interaktion mit der Software."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"OWS: Multilinguale Unterst\xfctzung"}),": Die Unterst\xfctzung von mehreren Sprachen macht uniWAHL zu einer international zug\xe4nglicheren Plattform f\xfcr die Stimmabgabe. Diese Funktion f\xf6rdert zudem die Wahlbeteiligung, indem sie die Barrieren durch Sprachunterschiede minimiert."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"OWS: Multiple Textfelder f\xfcr Write-ins"}),": Die Funktion mehrere Textfelder (z.B. Vorname, Nachname) zur Eingabe von Kandidierenden hinzuzuf\xfcgen, erm\xf6glicht es der Wahlleitung, individuelle Eingaben zu nachnominierten Personen besser zu strukturieren. Durch diese Funktion wird eine gr\xf6\xdfere Flexibilit\xe4t bei Nominierungswahlen oder Wahlen ohne Bindung an Wahlvorschl\xe4ge erm\xf6glicht, was die Effizienz des Wahlprozesses erh\xf6ht."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"OWS: Suchleiste f\xfcr gro\xdfe Stimmzettel"}),": Die neue (optionale) Suchleiste erm\xf6glicht eine effizientere Navigation auf Stimmzetteln mit zahlreichen Kandidierenden und hilft den W\xe4hlenden, bestimmte Listenwahlvorschl\xe4ge oder Personen schnell zu finden."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"OWS: Benutzerspezifische Rechte"}),": Die Funktion der benutzerspezifischen Rechte erm\xf6glicht eine granulare Kontrolle und Verwaltung der Zugriffsrechte f\xfcr verschiedene Benutzer im Online-Wahlsystem. Administratoren k\xf6nnen nun individuelle Rechte f\xfcr Wahlleitungen im Online-Wahlsystem vergeben, um sicherzustellen, dass diese auf die f\xfcr sie relevanten Bereiche der Software direkten Zugriff hat."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"OWS: Automatischer Start / Stop"}),": Die automatisierte Steuerung des Zeitpunkts zum Wahlstart und -ende erm\xf6glicht ein effizienteres Management des Wahlzeitraums und eine pr\xe4zise Kontrolle durch die Wahlleitung."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"OWS: Vorab-Ausz\xe4hlungen"}),": Stimmzettel k\xf6nnen nun bereits w\xe4hrend eines noch laufenden Wahlzeitraums ausgez\xe4hlt werden, dadurch k\xf6nnen Hochrechnungen und voraussichtliche Verteilungen von Sitzen ermittelt werden."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"uniSCAN: Fortlaufende Erzeugung der Erkennungssets"}),": Bei jeder Ausgabe eines Stimmzettels zum Einscannen wird nun automatisch die FormID hochgez\xe4hlt und in den Erkennungssets erg\xe4nzt, auch wenn es sich nur um eine Stimmzettel-Vorschau handelt."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"uniSCAN: \xdcberarbeitete Ausz\xe4hlungsprotokolle"}),": Die Ausz\xe4hlungsprotokolle (bzw. Importprotokolle) von uniSCAN wurden \xfcberarbeitet, um weniger Redundanzen zu enthalten, so dass die manuelle Verifikation der Ergebnisse erleichtert wird."]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"\u2699\ufe0fWeitere Neuerungen"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"HISinOne-Integration"}),": HISinOne ist das am meisten eingesetzte Campus Management System f\xfcr Hochschulen und Universit\xe4ten. Somit auch ein ideales Frontend f\xfcr die Authentifizierung am Online-Wahlsystem. Mittels der uniWAHL Authentifizierung f\xfcr HISinOne kann nun ein ausgesprochen sicherer und dennoch bequemer Zugang zur Online-Wahlurne zur Verf\xfcgung gestellt werden. Mit den von uns zur Verf\xfcgung gestellten Erweiterungen k\xf6nnen sowohl W\xe4hlerlisten in HISinOne erzeugt, als auch Portlets zum Wahlsystem f\xfcr wahlberechtigte Nutzer eingebunden werden."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Online-Kontrolle der Angaben zur Wahlberechtigung"}),": \xdcber den neuen Service uniWAHL OWS-Verzeichnispr\xfcfung kann jede wahlberechtigte Person online, ihren Eintrag zur Wahlberechtigung im Verzeichnis \xfcberpr\xfcfen. Die Wahlverzeichnispr\xfcfung erm\xf6glicht es den W\xe4hlenden somit, jederzeit und komfortabel die eigene Eintragung zur Wahlberechtigung im Verzeichnis abzufragen und gegebenenfalls notwendige \xc4nderungen direkt zu beantragen. Seitens der Wahlleitung k\xf6nnen Antworttexte definiert und nat\xfcrlich auch Fristen gesetzt werden."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Nominierung"}),": Die neue Benutzeroberfl\xe4che des Onlinewahlsystems ist nun auch darauf ausgelegt, Nominierungen \xfcber erweiterte Texteingabe-Felder in verschiedenen Konfigurationen (z.B. Anzahl nominierbarer Personen pro Wahlbereich, Anzahl der Texteingabefelder pro nominierter Person z.B. \u201eVorname\u201c, \u201eNachname\u201c, \u201eBereich\u201c) zu unterst\xfctzen. Die Gremienstruktur Ihrer Nominierung l\xe4sst sich bequem im uniWAHL Kernprodukt einrichten. Sie \xfcbergeben anschlie\xdfend ein pseudonymes Verzeichnis der Nominierungsberechtigten und unsere Experten legen die Nominierung im uniWAHL Online-Wahlsystem f\xfcr Sie an. Es k\xf6nnen alle g\xe4ngigen Zugangsverfahren zur Nominierung wie HISinOne oder SmartLink genutzt werden. Ist die Nominierung beendet, erhalten Sie einen Export der Ergebnisse und die M\xf6glichkeit zum Import in die uniWAHL Kernsoftware."]}),"\n"]})]})}function o(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(h,{...e})}):h(e)}},8453(e,n,i){i.d(n,{R:()=>l,x:()=>u});var r=i(6540);const t={},s=r.createContext(t);function l(e){const n=r.useContext(s);return r.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function u(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:l(e.components),r.createElement(s.Provider,{value:n},e.children)}}}]);